/**
 * `fx-refresh`
 *
 * Calls refresh() on fx-form
 *
 */
class FxRefresh extends AbstractAction {
  async perform() {
    this.dispatchEvent(new CustomEvent('execute-action', {
      composed: true,
      bubbles: true,
      cancelable: true,
      detail: {
        action: this,
        event: this.event
      }
    }));
    if (this.hasAttribute('self')) {
      const control = XPathUtil.getClosest('fx-control, fx-output, fx-upload', this);
      if (control) {
        control.refresh(true);
        return;
      }
    }
    if (this.hasAttribute('force')) {
      this.getOwnerForm().refresh(true);
      return;
    }
    if (this.hasAttribute('selector')) {
      const target = document.querySelector(this.getAttribute('selector'));
      if (target && Fore.isUiElement(target.nodeName) && typeof target.refresh === 'function') {
        target.refresh(true);
      }
      return;
    }
    if (this.hasAttribute('control')) {
      const targetId = this.getAttribute('control');
      let ctrl = resolveId(targetId, this);
      if (!ctrl) {
        ctrl = document.querySelector(`#${targetId}`);
      }
      if (ctrl && Fore.isUiElement(ctrl.nodeName) && typeof ctrl.refresh === 'function') {
        ctrl.refresh(true);
      }
      return;
    }
    this.getOwnerForm().refresh();
  }
}
if (!customElements.get('fx-refresh')) {
  window.customElements.define('fx-refresh', FxRefresh);
}

// import { FxAction } from './fx-action.js';

/**
 * `fx-replace` - replaces the node referred to with 'ref' with node referred to with 'with' attribute.
 *
 * @customElement
 */
class FxReplace extends AbstractAction {
  static get properties() {
    return {
      ...super.properties,
      with: {
        type: String
      },
      replaceNode: Object
    };
  }
  constructor() {
    super();
    this.with = '';
  }
  connectedCallback() {
    if (super.connectedCallback) {
      super.connectedCallback();
    }
    this.with = this.getAttribute('with');
  }
  async perform() {
    super.perform();
    // console.log('replace action variables', this.inScopeVariables);
    // if (!this.nodeset) {
    //   return;
    // }
    const target = evaluateXPathToFirstNode(this.with, this.nodeset, this);
    if (!target) return;
    this.replace(this.nodeset, target);
  }
  actionPerformed() {
    this.getModel().updateModel();
    this.getOwnerForm().refresh(true); //todo: optimize and update only the affected subtree
    this.dispatchActionPerformed();
  }
  replace(toReplace, replaceWith) {
    if (!toReplace || !replaceWith) return; // bail out silently
    if (!toReplace.nodeName || !replaceWith.nodeName) {
      return;
    }
    if (toReplace.nodeType === Node.ATTRIBUTE_NODE) {
      const {
        ownerElement
      } = toReplace;
      ownerElement.setAttribute(replaceWith.nodeName, replaceWith.textContent);
      ownerElement.removeAttribute(toReplace.nodeName);
    } else if (toReplace.nodeType === Node.ELEMENT_NODE) {
      const cloned = replaceWith.cloneNode(true);
      toReplace.replaceWith(cloned);
    }
    // todo: add selective update and create and notify modelItem for toReplace and replaceWith
    /*
    let replaceWithModelItem = this.getModel().getModelItem(replaceWith);
    if (!replaceWithModelItem) {
      const replaceWithModelItem = FxBind.createModelItem(
        this.getAttribute('with'),
        replaceWith,
        this,
        null,
      );
      this.getModel().registerModelItem(replaceWithModelItem);
      this.getOwnerForm().addToBatchedNotifications(replaceWithModelItem);
    }
    */
    // this.getModel().changed.push(modelitem);
    this.needsUpdate = true;
  }
}
if (!customElements.get('fx-replace')) {
  window.customElements.define('fx-replace', FxReplace);
}

